import{_ as d,o as e,c as i,ag as r}from"./chunks/framework.D9ghT4bC.js";const p=JSON.parse('{"title":"文明相关 JSON 文件","description":"","frontmatter":{"title":"文明相关 JSON 文件"},"headers":[],"relativePath":"zh/Modders/Mod-file-structure/2-Civilization-related-JSON-files.md","filePath":"zh/Modders/Mod-file-structure/2-Civilization-related-JSON-files.md"}'),a={name:"zh/Modders/Mod-file-structure/2-Civilization-related-JSON-files.md"};function s(n,t,o,l,h,c){return e(),i("div",null,[...t[0]||(t[0]=[r(`<h1 id="文明相关-json-文件" tabindex="-1">文明相关 JSON 文件 <a class="header-anchor" href="#文明相关-json-文件" aria-label="Permalink to &quot;文明相关 JSON 文件&quot;">​</a></h1><h2 id="beliefs-json" tabindex="-1">Beliefs.json <a class="header-anchor" href="#beliefs-json" aria-label="Permalink to &quot;Beliefs.json&quot;">​</a></h2><p><a href="https://github.com/yairm210/Unciv/blob/master/android/assets/jsons/Civ%20V%20-%20Gods%20%26%20Kings/Beliefs.json" target="_blank" rel="noreferrer">链接到原始文件</a></p><p>此文件包含你的模组中可以为宗教选择的信仰。</p><p>每个信仰具有以下结构：</p><table tabindex="0"><thead><tr><th>属性</th><th>类型</th><th>默认值</th><th>说明</th></tr></thead><tbody><tr><td>name</td><td>String</td><td>必需</td><td></td></tr><tr><td>type</td><td>Enum</td><td>必需</td><td>信仰类型。值必须是 Pantheon、Founder、Follower 或 Enhancer</td></tr><tr><td>uniques</td><td>List of Strings</td><td>空</td><td>此信仰为其追随城市添加的<a href="/Unciv/zh/Modders/uniques.html">独特能力</a>列表</td></tr><tr><td>civilopediaText</td><td>List</td><td>空</td><td>请参阅 <a href="/Unciv/zh/Modders/Mod-file-structure/5-Miscellaneous-JSON-files.html#civilopedia-文本">civilopediaText 章节</a></td></tr></tbody></table><h2 id="buildings-json" tabindex="-1">Buildings.json <a class="header-anchor" href="#buildings-json" aria-label="Permalink to &quot;Buildings.json&quot;">​</a></h2><p><a href="https://github.com/yairm210/Unciv/blob/master/android/assets/jsons/Civ%20V%20-%20Gods%20%26%20Kings/Buildings.json" target="_blank" rel="noreferrer">链接到原始文件</a></p><p>此文件包含你想要在模组中使用的所有建筑和奇观。</p><p>每个建筑具有以下结构：</p><table tabindex="0"><thead><tr><th>属性</th><th>类型</th><th>默认值</th><th>说明</th></tr></thead><tbody><tr><td>name</td><td>String</td><td>必需</td><td></td></tr><tr><td>cost</td><td>Integer</td><td>-1</td><td>建造建筑所需的生产力。如果为 -1，则使用 <code>requiredTech</code> 的 <code>buildingCost</code> <a href="#列结构">列</a></td></tr><tr><td><a href="/Unciv/zh/Modders/Mod-file-structure/3-Map-related-JSON-files.html#一般统计"><code>&lt;stats&gt;</code></a></td><td>Float</td><td>0</td><td>建筑产生的每回合收益</td></tr><tr><td>maintenance</td><td>Integer</td><td>0</td><td>建筑的维护费用</td></tr><tr><td>isWonder</td><td>Boolean</td><td>false</td><td>此建筑是否为全球奇观</td></tr><tr><td>isNationalWonder</td><td>Boolean</td><td>false</td><td>此建筑是否为国家奇观</td></tr><tr><td>requiredBuilding</td><td>String</td><td>none</td><td>在建造此建筑之前必须建造的建筑。必须在 <a href="#buildings-json">Buildings.json</a> 中</td></tr><tr><td>requiredTech</td><td>String</td><td>none</td><td>在建造此建筑之前必须研究的科技。必须在 <a href="#techs-json">Techs.json</a> 中</td></tr><tr><td>requiredResource</td><td>String</td><td>none</td><td>建造此建筑时消耗的资源。必须在 <a href="/Unciv/zh/Modders/Mod-file-structure/3-Map-related-JSON-files.html#tileresources-json">TileResources.json</a> 中</td></tr><tr><td>requiredNearbyImprovedResources</td><td>List of Strings</td><td>空</td><td>仅当此列表中的任何资源位于此城市的边界内并已改进时，才能建造此建筑。每个资源必须在 <a href="/Unciv/zh/Modders/Mod-file-structure/3-Map-related-JSON-files.html#tileresources-json">TileResources.json</a> 中</td></tr><tr><td>replaces</td><td>String</td><td>none</td><td>应被此建筑替换的建筑的名称。必须在 <a href="#buildings-json">Buildings.json</a> 中</td></tr><tr><td>uniqueTo</td><td>String</td><td>none</td><td>如果提供，则只有具有此名称的文明可以建造此建筑。必须在 <a href="#nations-json">Nations.json</a> 中</td></tr><tr><td>cityStrength</td><td>Integer</td><td>0</td><td>建造此建筑的城市获得的战斗力加成</td></tr><tr><td>cityHealth</td><td>Integer</td><td>0</td><td>建造此建筑的城市获得的生命值加成</td></tr><tr><td>hurryCostModifier</td><td>Integer</td><td>0</td><td>当使用金币或信仰购买此建筑时，价格增加此百分比</td></tr><tr><td>quote</td><td>String</td><td>none</td><td>如果此建筑是（国家）奇观，则此字符串将显示在完成弹窗上</td></tr><tr><td>uniques</td><td>List of Strings</td><td>空</td><td>此建筑具有的<a href="/Unciv/zh/Modders/uniques.html">独特能力</a>列表</td></tr><tr><td>replacementTextForUniques</td><td>String</td><td>none</td><td>如果提供，则显示此字符串而不是所有 uniques</td></tr><tr><td>percentStatBonus</td><td>Object</td><td>none</td><td>建筑提供的统计数据的百分比加成。格式与<a href="/Unciv/zh/Modders/Mod-file-structure/3-Map-related-JSON-files.html#专业统计数据">专业统计数据</a>相同（数字为百分比。例如，<code>[30]</code> 表示统计数据加成 30%）</td></tr><tr><td>greatPersonPoints</td><td>Object</td><td>none</td><td>此建筑每回合产生的伟人点数。有效键是单位名称（Great Scientist、Warrior 等），有效值是整数</td></tr><tr><td>specialistSlots</td><td>Object</td><td>none</td><td>此建筑提供的专家槽位。有效键是专家名称（在 <a href="#specialists-json">Specialists.json</a> 中定义），有效值是整数，为此专家提供的槽位数</td></tr><tr><td>civilopediaText</td><td>List</td><td>空</td><td>请参阅 <a href="/Unciv/zh/Modders/Mod-file-structure/5-Miscellaneous-JSON-files.html#civilopedia-文本">civilopediaText 章节</a></td></tr></tbody></table><h2 id="nations-json" tabindex="-1">Nations.json <a class="header-anchor" href="#nations-json" aria-label="Permalink to &quot;Nations.json&quot;">​</a></h2><p><a href="https://github.com/yairm210/Unciv/blob/master/android/assets/jsons/Civ%20V%20-%20Gods%20%26%20Kings/Nations.json" target="_blank" rel="noreferrer">链接到原始文件</a></p><p>此文件包含所有国家和城邦，包括野蛮人和观察者。</p><p>每个国家具有以下结构：</p><table tabindex="0"><thead><tr><th>属性</th><th>类型</th><th>默认值</th><th>说明</th></tr></thead><tbody><tr><td>name</td><td>String</td><td>必需</td><td></td></tr><tr><td>leaderName</td><td>String</td><td>none</td><td>仅城邦可以省略！如果你想要领袖头像，图像文件名必须完全匹配，包括大小写</td></tr><tr><td>style</td><td>String</td><td>none</td><td>附加到像素单位图像名称的修饰符</td></tr><tr><td>cityStateType</td><td>String</td><td>none</td><td>区分主要文明和城邦（必须在 <a href="#citystatetypes-json">CityStateTypes.json</a> 中）</td></tr><tr><td>startBias</td><td>List of strings</td><td>空</td><td>以下的一个或多个：<a href="/Unciv/zh/Modders/Unique-parameters.html#terrainfilter">terrainFilter</a> 或 &quot;Avoid [terrainFilter]&quot;。[^S]</td></tr><tr><td>preferredVictoryType</td><td>String</td><td>Neutral</td><td>主要文明将追求的胜利类型（无需在 <a href="/Unciv/zh/Modders/Mod-file-structure/5-Miscellaneous-JSON-files.html#victorytypes-json">VictoryTypes.json</a> 中指定）</td></tr><tr><td>personality</td><td>String</td><td>none</td><td>在 <a href="#personalitiesjson">Personalities.json</a> 中指定的个性的名称</td></tr><tr><td>favoredReligion</td><td>String</td><td>none</td><td>主要文明在创立宗教时（如果可用）将选择的宗教。必须在 <a href="#religions-json">Religions.json</a> 中</td></tr><tr><td>startIntroPart1</td><td>String</td><td>none</td><td>游戏开始时向玩家显示的介绍性文字...[^V]</td></tr><tr><td>startIntroPart2</td><td>String</td><td>none</td><td>...第二段。___不要___使用&quot;TBD&quot;！！！留空以跳过该警报。</td></tr><tr><td>declaringWar</td><td>String</td><td>none</td><td>另一个问候，支持语音挂钩 [^V]</td></tr><tr><td>attacked</td><td>String</td><td>none</td><td>另一个问候，支持语音挂钩 [^V]</td></tr><tr><td>defeated</td><td>String</td><td>none</td><td>另一个问候，支持语音挂钩 [^V]</td></tr><tr><td>denounced</td><td>String</td><td>none</td><td>另一个问候，支持语音挂钩 [^V]</td></tr><tr><td>introduction</td><td>String</td><td>none</td><td>另一个问候，支持语音挂钩 [^V]</td></tr><tr><td>neutralHello</td><td>String</td><td>none</td><td>另一个问候，支持语音挂钩 [^V]</td></tr><tr><td>hateHello</td><td>String</td><td>none</td><td>另一个问候，支持语音挂钩 [^V]</td></tr><tr><td>tradeRequest</td><td>String</td><td>none</td><td>另一个问候，支持语音挂钩 [^V]</td></tr><tr><td>declaringFriendship</td><td>String</td><td>none</td><td>另一个问候，支持语音挂钩 [^V]</td></tr><tr><td>innerColor</td><td><a href="/Unciv/zh/Modders/Mod-file-structure/5-Miscellaneous-JSON-files.html#rgb-颜色列表">List of 3× Integer</a></td><td>black</td><td>国家图标外环的 RGB 颜色</td></tr><tr><td>outerColor</td><td><a href="/Unciv/zh/Modders/Mod-file-structure/5-Miscellaneous-JSON-files.html#rgb-颜色列表">List of 3× Integer</a></td><td>必需</td><td>国家图标内圈的 RGB 颜色</td></tr><tr><td>uniqueName</td><td>String</td><td>none</td><td>此国家特殊特征的装饰性名称</td></tr><tr><td>uniqueText</td><td>String</td><td>none</td><td>&quot;uniques&quot;的替换文本。如果为空，则单独列出 uniques</td></tr><tr><td>uniques</td><td>List</td><td>空</td><td>此文明具有的<a href="/Unciv/zh/Modders/uniques.html">独特能力</a>列表</td></tr><tr><td>cities</td><td>List</td><td>空</td><td>按顺序用于新建立城市的城市名称。主要文明和城邦必需</td></tr><tr><td>civilopediaText</td><td>List</td><td>空</td><td>请参阅 <a href="/Unciv/zh/Modders/Mod-file-structure/5-Miscellaneous-JSON-files.html#civilopedia-文本">civilopediaText 章节</a></td></tr></tbody></table><p>[^S]: &quot;Coast&quot;偏好（_除非_与&quot;Avoid&quot;结合）被转换为对沿海地块、湖泊旁地块、河流地块或近河地块的复杂测试，并且这些文明首先被处理。在这种情况下，将忽略其他 startBias 条目。 其他正面（没有&quot;Avoid&quot;）的 startBias 接下来被处理。多个正面偏好被视为相等，但不会获得&quot;回退&quot;。 单个正面 startBias 如果没有（或不再有）具有该主要类型的区域，则可以获得&quot;回退&quot;区域：任何具有尽可能多的指定地形的剩余区域都可以。 多个&quot;Avoid&quot;条目被视为相等（并降低成功的机会 - 如果没有区域避免_所有_指定类型，该文明会获得一个随机区域）。 当组合偏好地形与&quot;Avoid&quot;时，后者优先，并且在选择非要避免类型的区域时，偏好地形只有次要权重。 这些注释__仅__在生成的地图上玩游戏时有效，从地图编辑器加载的地图没有&quot;区域&quot;，并且 startBias 处理方式不同（但你可以期望单条目 startBias 效果最好）。</p><p>[^V]: 请参阅 <a href="/Unciv/zh/Modders/Images-and-Audio.html#提供领袖声音">提供领袖声音</a></p><h2 id="personalities-json" tabindex="-1">Personalities.json <a class="header-anchor" href="#personalities-json" aria-label="Permalink to &quot;Personalities.json&quot;">​</a></h2><p><a href="https://github.com/yairm210/Unciv/blob/master/android/assets/jsons/Civ%20V%20-%20Gods%20%26%20Kings/Personalities.json" target="_blank" rel="noreferrer">链接到原始文件</a></p><p>此文件包含计算机玩家的所有个性。</p><p>每个个性具有以下结构：</p><table tabindex="0"><thead><tr><th>属性</th><th>类型</th><th>默认值</th><th>说明</th></tr></thead><tbody><tr><td>name</td><td>String</td><td>必需</td><td></td></tr><tr><td>preferredVictoryType</td><td>String</td><td>Neutral</td><td>主要文明将追求的胜利类型（无需在 <a href="/Unciv/zh/Modders/Mod-file-structure/5-Miscellaneous-JSON-files.html#victorytypes-json">VictoryTypes.json</a> 中指定）</td></tr><tr><td><a href="/Unciv/zh/Modders/Mod-file-structure/3-Map-related-JSON-files.html#一般统计"><code>&lt;stats&gt;</code></a>, <a href="/Unciv/zh/Modders/Mod-file-structure/2-Civilization-related-JSON-files.html#个性行为"><code>&lt;behaviors&gt;</code></a></td><td>Float</td><td>5</td><td>计算机玩家对统计数据的关注程度。通常范围从 0（不关注）到 10（双倍关注）</td></tr><tr><td>priorities</td><td>Object</td><td>none</td><td>每个政策分支的优先级 [^B]</td></tr><tr><td>uniques</td><td>List</td><td>空</td><td>此个性具有的<a href="/Unciv/zh/Modders/uniques.html">独特能力</a>列表</td></tr><tr><td>civilopediaText</td><td>List</td><td>空</td><td>请参阅 <a href="/Unciv/zh/Modders/Mod-file-structure/5-Miscellaneous-JSON-files.html#civilopedia-文本">civilopediaText 章节</a></td></tr></tbody></table><p>[^B]: 类似于 <a href="#分支优先级">政策优先级</a> &quot;priorities&quot;对象定义主要文明的 AI 对政策分支的优先级。AI 为其首选胜利类型选择编号最高的政策分支。如果两个或更多候选分支具有相同的优先级，AI 在候选分支中随机选择一个。</p><p>该对象使用政策分支名称和整数将政策分支映射到主要文明的优先级值。任何未列出的分支的默认值为 0</p><p>下面的代码是有效的&quot;priorities&quot;定义的示例。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&quot;priorities&quot;: {</span></span>
<span class="line"><span>    &quot;Tradition&quot;: 30,</span></span>
<span class="line"><span>    &quot;Liberty&quot;: 20,</span></span>
<span class="line"><span>    &quot;Honor&quot;: 10</span></span>
<span class="line"><span>}</span></span></code></pre></div><h3 id="个性行为" tabindex="-1">个性行为 <a class="header-anchor" href="#个性行为" aria-label="Permalink to &quot;个性行为&quot;">​</a></h3><p>个性行为<strong>尚未完全实现</strong>，其名称可能会更改。在它们准备好之前使用它们可能会使模组无法游玩。<em><strong>以下是 WIP - 阅读风险自负！</strong></em></p><p>有 7 种定义行为会影响 AI 文明的行为。较高的值意味着它们的行为更像该属性。</p><ul><li>Military：决定文明对建造军队的重视程度，但不一定是使用军队。较高的值意味着更关注军事，较低的值意味着它可能更和平。</li><li>Agressive：决定文明在战争期间如何使用其单位以及它们优先考虑哪些建筑。较高的值意味着文明更具攻击性，较低的值意味着它更具防御性。</li><li>War：决定文明宣战的可能性。0 表示文明根本不会宣战。</li><li>Commerce：决定文明对贸易、开放边界和解放城邦的开放程度。较高的值意味着即使与不喜欢的文明也有更高的贸易频率。</li><li>Diplomacy：决定文明宣布友谊、防御条约、和平条约或其他外交行动的可能性。</li><li>Loyal：决定文明对持久联盟的重视程度，加入战争意愿，以及鄙视其他不可靠文明的程度。</li><li>Expansion：决定文明对新城市建立或征服的关注程度。较低的值意味着它们可能更关注文化。</li></ul><h2 id="citystatetypes-json" tabindex="-1">CityStateTypes.json <a class="header-anchor" href="#citystatetypes-json" aria-label="Permalink to &quot;CityStateTypes.json&quot;">​</a></h2><p><a href="https://github.com/yairm210/Unciv/blob/master/android/assets/jsons/Civ%20V%20-%20Gods%20%26%20Kings/CityStateTypes.json" target="_blank" rel="noreferrer">链接到原始文件</a></p><p>此可选文件用于定义城邦的类型。这些类型决定了主要文明在通过影响力与城邦结交或结盟时获得的利益。 对于基础规则集模组，如果省略文件或包含空列表，则<a href="https://github.com/yairm210/Unciv/blob/master/android/assets/jsons/Civ%20V%20-%20Vanilla/CityStateTypes.json" target="_blank" rel="noreferrer">来自 Vanilla 规则集的所有类型</a>会自动添加： Cultured、Maritime、Mercantile、Militaristic、Religious。</p><p>每个城邦类型具有以下结构：</p><table tabindex="0"><thead><tr><th>属性</th><th>类型</th><th>默认值</th><th>说明</th></tr></thead><tbody><tr><td>name</td><td>String</td><td>必需</td><td></td></tr><tr><td>friendBonusUniques</td><td>List of Strings</td><td>空</td><td>当与此城邦结交时授予主要文明的<a href="/Unciv/zh/Modders/uniques.html">独特能力</a>列表</td></tr><tr><td>allyBonusUniques</td><td>List of Strings</td><td>空</td><td>当与城邦结盟时授予主要文明的<a href="/Unciv/zh/Modders/uniques.html">独特能力</a>列表</td></tr><tr><td>color</td><td><a href="/Unciv/zh/Modders/Mod-file-structure/5-Miscellaneous-JSON-files.html#rgb-颜色列表">List of 3× Integer</a></td><td>[255, 255, 255]</td><td>文明百科中文字的 RGB 颜色</td></tr></tbody></table><h2 id="policies-json" tabindex="-1">Policies.json <a class="header-anchor" href="#policies-json" aria-label="Permalink to &quot;Policies.json&quot;">​</a></h2><p><a href="https://github.com/yairm210/Unciv/blob/master/android/assets/jsons/Civ%20V%20-%20Gods%20%26%20Kings/Policies.json" target="_blank" rel="noreferrer">链接到原始文件</a></p><p>此文件包含所有可以用文化&quot;购买&quot;的社会政策。</p><p>它们组织在&#39;分支&#39;中，每个分支有一个&#39;开启者&#39;、一个或多个&#39;成员&#39;政策和一个&#39;完成者&#39;。因此，此文件使用两个级别进行组织 - 分支和成员政策。</p><p>&#39;开启者&#39;的属性在分支级别定义，而&#39;完成者&#39;是成员级别的一个条目，_必须_命名为 <code>分支名称 + &quot; Complete&quot;</code>，区分大小写。例如，政策分支&quot;Tradition&quot;的完成者将具有名称&quot;Tradition Complete&quot;。</p><h3 id="分支结构" tabindex="-1">分支结构 <a class="header-anchor" href="#分支结构" aria-label="Permalink to &quot;分支结构&quot;">​</a></h3><p>每个政策分支具有以下结构：</p><table tabindex="0"><thead><tr><th>属性</th><th>类型</th><th>默认值</th><th>说明</th></tr></thead><tbody><tr><td>name</td><td>String</td><td>必需</td><td></td></tr><tr><td>era</td><td>String</td><td>必需</td><td>解锁时代，如 <a href="/Unciv/zh/Modders/Mod-file-structure/5-Miscellaneous-JSON-files.html#eras-json">Eras.json</a> 中定义</td></tr><tr><td>priorities</td><td>Object</td><td>none</td><td>每个胜利类型的优先级，<a href="#分支优先级">请参阅此处</a></td></tr><tr><td>uniques</td><td>List</td><td>空</td><td>采用此政策分支时授予的<a href="/Unciv/zh/Modders/uniques.html">独特能力</a>列表</td></tr><tr><td>civilopediaText</td><td>List</td><td>空</td><td>请参阅 <a href="/Unciv/zh/Modders/Mod-file-structure/5-Miscellaneous-JSON-files.html#civilopedia-文本">civilopediaText 章节</a></td></tr><tr><td>policies</td><td>List</td><td>空</td><td><a href="#成员政策结构">成员政策</a>和<a href="#分支完成者结构">分支&#39;完成者&#39;</a>列表 - 注意 {} 和 [] 的嵌套</td></tr></tbody></table><h4 id="成员政策结构" tabindex="-1">成员政策结构 <a class="header-anchor" href="#成员政策结构" aria-label="Permalink to &quot;成员政策结构&quot;">​</a></h4><table tabindex="0"><thead><tr><th>属性</th><th>类型</th><th>默认值</th><th>说明</th></tr></thead><tbody><tr><td>name</td><td>String</td><td>必需</td><td></td></tr><tr><td>row</td><td>Integer</td><td>必需</td><td>UI 中的放置，每个单位大约是图标大小的一半</td></tr><tr><td>column</td><td>Integer</td><td>必需</td><td>UI 中的放置，每个单位大约是图标大小的一半</td></tr><tr><td>requires</td><td>List</td><td>空</td><td>先决政策名称列表</td></tr><tr><td>uniques</td><td>List</td><td>空</td><td>采用此政策成员时授予的<a href="/Unciv/zh/Modders/uniques.html">独特能力</a>列表</td></tr><tr><td>civilopediaText</td><td>List</td><td>空</td><td>请参阅 <a href="/Unciv/zh/Modders/Mod-file-structure/5-Miscellaneous-JSON-files.html#civilopedia-文本">civilopediaText 章节</a></td></tr></tbody></table><h4 id="分支完成者结构" tabindex="-1">分支完成者结构 <a class="header-anchor" href="#分支完成者结构" aria-label="Permalink to &quot;分支完成者结构&quot;">​</a></h4><table tabindex="0"><thead><tr><th>属性</th><th>类型</th><th>默认值</th><th>说明</th></tr></thead><tbody><tr><td>name</td><td>String</td><td>必需</td><td></td></tr><tr><td>uniques</td><td>List</td><td>空</td><td>采用分支中所有政策成员时授予的<a href="/Unciv/zh/Modders/uniques.html">独特能力</a>列表</td></tr><tr><td>civilopediaText</td><td>List</td><td>空</td><td>请参阅 <a href="/Unciv/zh/Modders/Mod-file-structure/5-Miscellaneous-JSON-files.html#civilopedia-文本">civilopediaText 章节</a></td></tr></tbody></table><h3 id="分支优先级" tabindex="-1">分支优先级 <a class="header-anchor" href="#分支优先级" aria-label="Permalink to &quot;分支优先级&quot;">​</a></h3><p>&quot;priorities&quot;对象定义主要文明的 AI 对政策分支的优先级。AI 选择此处列出的首选胜利类型的最高总和与个性中列出的编号之和最高的政策分支。如果两个或更多候选分支具有相同的优先级，AI 在候选分支中随机选择一个。</p><p>该对象使用字符串和整数将胜利类型映射到主要文明的优先级值。如果未指定首选胜利类型，则默认优先级值设置为 0。</p><p>下面的代码是有效的&quot;priorities&quot;定义的示例。</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;priorities&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;Neutral&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;Cultural&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">10</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;Diplomatic&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;Domination&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;Scientific&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">10</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><h2 id="quests-json" tabindex="-1">Quests.json <a class="header-anchor" href="#quests-json" aria-label="Permalink to &quot;Quests.json&quot;">​</a></h2><p><a href="https://github.com/yairm210/Unciv/blob/master/android/assets/jsons/Civ%20V%20-%20Gods%20%26%20Kings/Quests.json" target="_blank" rel="noreferrer">链接到原始文件</a></p><p>此文件包含城邦可能给予主要文明的任务。</p><p>每个任务具有以下结构：</p><table tabindex="0"><thead><tr><th>属性</th><th>类型</th><th>默认值</th><th>说明</th></tr></thead><tbody><tr><td>name</td><td>String</td><td>必需</td><td>定义任务标准，<a href="#任务名称">请参阅下文</a></td></tr><tr><td>description</td><td>String</td><td>必需</td><td>向玩家显示的任务描述。可以根据 <code>name</code> 添加额外信息，<a href="#任务名称">请参阅下文</a></td></tr><tr><td>type</td><td>Enum</td><td>Individual</td><td>Individual 或 Global</td></tr><tr><td>influence</td><td>Float</td><td>40</td><td>任务完成时获得的影响力奖励</td></tr><tr><td>duration</td><td>Integer</td><td>0</td><td>完成任务的最大回合数。如果为 0，则没有回合限制</td></tr><tr><td>minimumCivs</td><td>Integer</td><td>1</td><td>开始任务所需的最少文明数。仅对 type = Global 有意义</td></tr><tr><td>weightForCityStateType</td><td>Object</td><td>none</td><td>对每个<a href="#citystatetypes-json">城邦类型</a>或城邦个性（Friendly、Neutral、Hostile、Irrational）的此任务的相对权重乘数，<a href="#任务权重">请参阅下文</a></td></tr></tbody></table><h3 id="任务名称" tabindex="-1">任务名称 <a class="header-anchor" href="#任务名称" aria-label="Permalink to &quot;任务名称&quot;">​</a></h3><p>任务的名称定义任务的标准。如果它们在预定义枚举中未定义，则它们不会有行为。在描述中，任务描述中的方括号 <code>[]</code> 被额外信息替换（<code>Invest</code> 除外）。预定义任务名称列表如下：</p><table tabindex="0"><thead><tr><th>名称</th><th>标准</th><th>额外信息</th></tr></thead><tbody><tr><td>Route</td><td>使用道路或铁路将城邦连接到主要文明的首都</td><td></td></tr><tr><td>Clear Barbarian Camp</td><td>摧毁目标野蛮人营地</td><td></td></tr><tr><td>Construct Wonder</td><td>建造目标奇观</td><td>目标 <code>wonder</code></td></tr><tr><td>Connect Resource</td><td>将目标资源连接到主要文明的贸易网络</td><td>目标 <code>tileResource</code></td></tr><tr><td>Acquire Great Person</td><td>获得目标伟人</td><td>目标 <code>greatPerson</code></td></tr><tr><td>Conquer City State</td><td>击败目标城邦</td><td>目标 <code>cityState</code></td></tr><tr><td>Find Player</td><td>遇见目标主要文明</td><td>目标 <code>civName</code></td></tr><tr><td>Find Natural Wonder</td><td>发现目标自然奇观</td><td>目标 <code>naturalWonder</code></td></tr><tr><td>Give Gold</td><td>向城邦捐赠金币（金额不重要）</td><td>城邦的 <code>civName</code> &quot;bully&quot;</td></tr><tr><td>Pledge to Protect</td><td>承诺保护城邦</td><td>城邦的 <code>civName</code> &quot;bully&quot;</td></tr><tr><td>Contest Culture</td><td>在持续时间内成为文化增长最高的主要文明</td><td>主要文明的 <code>cultureGrowth</code></td></tr><tr><td>Contest Faith</td><td>在持续时间内成为信仰增长最高的主要文明</td><td>主要文明的 <code>faithGrowth</code></td></tr><tr><td>Contest Technology</td><td>在持续时间内研究科技最多的主要文明</td><td>主要文明的 <code>techsResearched</code></td></tr><tr><td>Invest</td><td>捐赠金币根据提供的价值产生额外影响力</td><td><strong>重要</strong>：方括号中的值是额外影响力的百分比。例如，[50] 表示 50%</td></tr><tr><td>Bully City State</td><td>向目标城邦索取贡品</td><td>目标 <code>city state</code></td></tr><tr><td>Denounce Civilization</td><td>谴责&quot;霸凌&quot;城邦的主要文明</td><td>城邦的 <code>civName</code> &quot;bully&quot;</td></tr><tr><td>Spread Religion</td><td>将主要文明的宗教传播到城邦</td><td>主要文明的 <code>religionName</code></td></tr></tbody></table><h3 id="任务权重" tabindex="-1">任务权重 <a class="header-anchor" href="#任务权重" aria-label="Permalink to &quot;任务权重&quot;">​</a></h3><p>&quot;weightForCityStateType&quot;对象确定任务的权重乘数。当城邦发起任务时，初始权重为 1，并根据<a href="#citystatetypes-json">城邦类型</a>和个性（Friendly、Neutral、Hostile、Irrational）乘以值。然后 AI 根据最终加权值随机选择一个任务。</p><p>该对象使用字符串到浮点数将城邦类型和个性映射到城邦的权重乘数。如果未找到首选胜利类型，则默认乘数为 1。</p><p>下面的代码是有效的&quot;weightForCityStateType&quot;定义的示例。在这种情况下，友好的军事主义城邦选择此任务的可能性是权重为 1 的任务的 0.4（0.2 × 2）倍。</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;weightForCityStateType&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;Hostile&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">2</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;Friendly&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0.2</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;Militaristic&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">2</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><h2 id="religions-json" tabindex="-1">Religions.json <a class="header-anchor" href="#religions-json" aria-label="Permalink to &quot;Religions.json&quot;">​</a></h2><p><a href="https://github.com/yairm210/Unciv/tree/master/android/assets/jsons/Civ%20V%20-%20Gods%20&amp;%20Kings/Religions.json" target="_blank" rel="noreferrer">链接到原始文件</a></p><p>这只是一个字符串列表，指定所有预定义的宗教名称。必须存在相应的图标，仅此而已。毕竟，它们只是<a href="#beliefs-json">信仰</a>的容器。</p><h2 id="specialists-json" tabindex="-1">Specialists.json <a class="header-anchor" href="#specialists-json" aria-label="Permalink to &quot;Specialists.json&quot;">​</a></h2><p><a href="https://github.com/yairm210/Unciv/blob/master/android/assets/jsons/Civ%20V%20-%20Gods%20%26%20Kings/Specialists.json" target="_blank" rel="noreferrer">链接到原始文件</a></p><p>此文件应包含公民可以分配的所有可能专家的列表。</p><p>每个专家具有以下结构：</p><table tabindex="0"><thead><tr><th>属性</th><th>类型</th><th>默认值</th><th>说明</th></tr></thead><tbody><tr><td>name</td><td>String</td><td>必需</td><td></td></tr><tr><td><a href="/Unciv/zh/Modders/Mod-file-structure/3-Map-related-JSON-files.html#一般统计"><code>&lt;stats&gt;</code></a></td><td>Float</td><td>0</td><td>专家产生的每回合收益</td></tr><tr><td>color</td><td><a href="/Unciv/zh/Modders/Mod-file-structure/5-Miscellaneous-JSON-files.html#rgb-颜色列表">List of 3× Integer</a></td><td>必需</td><td>此专家图像的颜色</td></tr><tr><td>greatPersonPoints</td><td>Object</td><td>none</td><td>此专家每回合产生的伟人点数。有效键是单位名称（Great Scientist、Warrior 等），有效值是整数</td></tr></tbody></table><h2 id="techs-json" tabindex="-1">Techs.json <a class="header-anchor" href="#techs-json" aria-label="Permalink to &quot;Techs.json&quot;">​</a></h2><p><a href="https://github.com/yairm210/Unciv/blob/master/android/assets/jsons/Civ%20V%20-%20Gods%20%26%20Kings/Techs.json" target="_blank" rel="noreferrer">链接到原始文件</a></p><p>此文件包含所有可以用科学研究的科技。它组织为外部&#39;列&#39;列表，其中每列包含一个或多个科技。</p><h3 id="列结构" tabindex="-1">列结构 <a class="header-anchor" href="#列结构" aria-label="Permalink to &quot;列结构&quot;">​</a></h3><p>每个科技列具有以下结构：</p><table tabindex="0"><thead><tr><th>属性</th><th>类型</th><th>默认值</th><th>说明</th></tr></thead><tbody><tr><td>columnNumber</td><td>Integer</td><td>必需</td><td>科技树中的水平放置</td></tr><tr><td>era</td><td>String</td><td>必需</td><td>确定研究此列中任何科技后达到的时代。必须在 <a href="/Unciv/zh/Modders/Mod-file-structure/5-Miscellaneous-JSON-files.html#eras-json">Eras.json</a> 中</td></tr><tr><td>techCost</td><td>Integer</td><td>0</td><td>此列中科技的默认成本</td></tr><tr><td>buildingCost</td><td>Integer</td><td>必需</td><td>需要此科技的建筑的默认成本</td></tr><tr><td>wonderCost</td><td>Integer</td><td>必需</td><td>需要此科技的奇观的默认成本</td></tr><tr><td>techs</td><td>List</td><td>必需</td><td><a href="#科技结构">科技</a>列表 - 注意 {} 和 [] 的嵌套</td></tr></tbody></table><h4 id="科技结构" tabindex="-1">科技结构 <a class="header-anchor" href="#科技结构" aria-label="Permalink to &quot;科技结构&quot;">​</a></h4><table tabindex="0"><thead><tr><th>属性</th><th>类型</th><th>默认值</th><th>说明</th></tr></thead><tbody><tr><td>name</td><td>String</td><td>必需</td><td></td></tr><tr><td>row</td><td>Integer</td><td>0</td><td>科技树中的垂直放置，每列必须唯一</td></tr><tr><td>cost</td><td>Integer</td><td><a href="#列结构">列 techCost</a></td><td>研究此科技所需的科学数量</td></tr><tr><td>prerequisites</td><td>List of Strings</td><td>空</td><td>此科技的先决科技名称列表。仅需要直接先决科技</td></tr><tr><td>quote</td><td>String</td><td>none</td><td>玩家研究此科技时呈现的一个好故事</td></tr><tr><td>uniques</td><td>List of Strings</td><td>空</td><td>此科技授予的<a href="/Unciv/zh/Modders/uniques.html">独特能力</a>列表</td></tr><tr><td>civilopediaText</td><td>List</td><td>空</td><td>请参阅 <a href="/Unciv/zh/Modders/Mod-file-structure/5-Miscellaneous-JSON-files.html#civilopedia-文本">civilopediaText 章节</a></td></tr></tbody></table>`,82)])])}const g=d(a,[["render",s]]);export{p as __pageData,g as default};
